//! Integration tests: real libmpv playback, headless, with fixtures generated by ffmpeg.
//!
//! Mirrors the playback cases of the Python Lumen test suite.

use std::path::PathBuf;
use std::process::Command;
use std::sync::{Mutex, MutexGuard, OnceLock};
use std::thread::sleep;
use std::time::{Duration, Instant};

use lumen_rs::engine::{Engine, Output, TrackKind};
use lumen_rs::session::{Session, State};
use lumen_rs::store::Store;

static SERIAL: Mutex<()> = Mutex::new(());
static MEDIA: OnceLock<Option<PathBuf>> = OnceLock::new();

fn ffmpeg(args: &[&str]) {
    let status = Command::new("ffmpeg")
        .args(["-hide_banner", "-loglevel", "error", "-y"])
        .args(args)
        .status()
        .unwrap();
    assert!(status.success(), "ffmpeg {args:?} failed");
}

fn make_fixtures() -> Option<PathBuf> {
    if Command::new("ffmpeg").arg("-version").output().is_err() {
        return None;
    }
    let root = tempfile::tempdir().unwrap().keep();
    let video = ["-f", "lavfi", "-i", "testsrc=size=320x180:rate=24"];
    let tone = |hz: u32| {
        [
            "-f".to_owned(),
            "lavfi".to_owned(),
            "-i".to_owned(),
            format!("sine=frequency={hz}"),
        ]
    };
    let path = |p: &str| root.join(p).to_string_lossy().into_owned();

    for dir in ["show", "single"] {
        std::fs::create_dir(root.join(dir)).unwrap();
    }
    for (name, dir) in [
        ("ep1", "show"),
        ("ep2", "show"),
        ("ep10", "show"),
        ("film", "single"),
    ] {
        let mut args: Vec<String> = video.iter().map(|s| s.to_string()).collect();
        args.extend(tone(440));
        args.extend(["-t", "30", "-c:v", "mpeg4", "-c:a", "aac"].map(String::from));
        args.push(path(&format!("{dir}/{name}.mp4")));
        ffmpeg(&args.iter().map(String::as_str).collect::<Vec<_>>());
    }

    ffmpeg(
        &[
            &video[..],
            &[
                "-f",
                "lavfi",
                "-i",
                "sine=frequency=440",
                "-t",
                "20",
                "-c:v",
                "mpeg4",
                "-c:a",
                "aac",
                &path("clip.mp4"),
            ],
        ]
        .concat(),
    );
    std::fs::write(
        root.join("chapters.txt"),
        ";FFMETADATA1\n[CHAPTER]\nTIMEBASE=1/1000\nSTART=0\nEND=10000\ntitle=Intro\n[CHAPTER]\nTIMEBASE=1/1000\nSTART=10000\nEND=20000\ntitle=Main\n",
    )
    .unwrap();
    ffmpeg(&[
        "-i",
        &path("clip.mp4"),
        "-i",
        &path("chapters.txt"),
        "-map_metadata",
        "1",
        "-map_chapters",
        "1",
        "-c",
        "copy",
        &path("chapters.mkv"),
    ]);

    std::fs::write(
        root.join("subs.srt"),
        "1\n00:00:00,000 --> 00:00:19,000\nHello\n",
    )
    .unwrap();
    ffmpeg(
        &[
            &video[..],
            &[
                "-f",
                "lavfi",
                "-i",
                "sine=frequency=440",
                "-f",
                "lavfi",
                "-i",
                "sine=frequency=880",
                "-i",
                &path("subs.srt"),
            ],
            &[
                "-map", "0", "-map", "1", "-map", "2", "-map", "3", "-t", "20",
            ],
            &[
                "-metadata:s:a:0",
                "language=eng",
                "-metadata:s:a:1",
                "language=jpn",
            ],
            &[
                "-c:v",
                "mpeg4",
                "-c:a",
                "aac",
                "-c:s",
                "srt",
                &path("tracks.mkv"),
            ],
        ]
        .concat(),
    );
    Some(root)
}

struct Fixture {
    root: PathBuf,
    _guard: MutexGuard<'static, ()>,
}

impl Fixture {
    fn path(&self, name: &str) -> String {
        self.root.join(name).to_string_lossy().into_owned()
    }
}

/// Serialises the tests (each opens a real player) and skips them when ffmpeg is missing.
fn fixture() -> Option<Fixture> {
    let guard = SERIAL.lock().unwrap_or_else(|e| e.into_inner());
    let root = MEDIA.get_or_init(make_fixtures).clone();
    if root.is_none() {
        eprintln!("skipped: ffmpeg is needed to generate fixtures");
    }
    Some(Fixture {
        root: root?,
        _guard: guard,
    })
}

fn session() -> Session {
    Session::new(
        Engine::new(Output::Headless, 80).unwrap(),
        Store::in_memory(),
    )
}

/// Ticks the session until `condition` holds, like the UI's 200 ms timer would.
fn wait(session: &mut Session, seconds: u64, mut condition: impl FnMut(&Session) -> bool) -> bool {
    let end = Instant::now() + Duration::from_secs(seconds);
    while Instant::now() < end {
        session.tick();
        if condition(session) {
            return true;
        }
        sleep(Duration::from_millis(20));
    }
    false
}

/// Waits until the position stops changing, e.g. after an asynchronous frame step.
fn settled_position(session: &mut Session) -> i64 {
    let mut last = -1;
    for _ in 0..50 {
        session.tick();
        let now = session.position_ms();
        if now == last {
            return now;
        }
        last = now;
        sleep(Duration::from_millis(120));
    }
    last
}

fn play(session: &mut Session, path: &str) {
    session.add(&[path.to_owned()], true);
    assert!(
        wait(session, 8, |s| s.state() == State::Playing
            && s.position_ms() > 0),
        "{path} did not start"
    );
}

#[test]
fn resumes_where_it_stopped_and_remembers_sync_per_file() {
    let Some(fx) = fixture() else { return };
    let mut s = session();
    play(&mut s, &fx.path("show/ep1.mp4"));
    s.seek_ms(12_000);
    assert!(wait(&mut s, 5, |s| s.position_ms() >= 12_000));
    s.shift_delay(TrackKind::Audio, 50);
    s.shift_delay(TrackKind::Subtitle, -100);

    s.add(&[fx.path("show/ep2.mp4")], true);
    assert!(wait(&mut s, 8, |s| s.state() == State::Playing
        && s.source().is_some_and(|p| p.ends_with("ep2.mp4"))));
    assert!(
        wait(&mut s, 3, |s| s.engine.delay_ms(TrackKind::Audio) == 0),
        "ep2 must not inherit ep1's sync"
    );

    s.play_index(0, None, false);
    assert!(
        wait(&mut s, 8, |s| s.position_ms() >= 11_000),
        "did not resume near 12 s"
    );
    assert!(
        wait(&mut s, 3, |s| s.engine.delay_ms(TrackKind::Audio) == 50),
        "audio delay not restored"
    );
    assert_eq!(s.engine.delay_ms(TrackKind::Subtitle), -100);
}

#[test]
fn restart_ignores_the_saved_position() {
    let Some(fx) = fixture() else { return };
    let mut s = session();
    play(&mut s, &fx.path("single/film.mp4"));
    s.seek_ms(10_000);
    assert!(wait(&mut s, 5, |s| s.position_ms() >= 10_000));
    s.stop();
    s.play_index(0, Some(0), false);
    assert!(wait(&mut s, 5, |s| s.state() == State::Playing));
    assert!(
        s.position_ms() < 3_000,
        "an explicit start overrides resume"
    );
}

#[test]
fn volume_speed_and_bookmarks() {
    let Some(fx) = fixture() else { return };
    let mut s = session();
    play(&mut s, &fx.path("show/ep1.mp4"));
    s.set_volume(180);
    assert!(wait(&mut s, 3, |s| s.engine.volume() == 180));
    assert_eq!(s.store.settings.volume, 180);
    s.set_volume(500);
    assert_eq!(s.store.settings.volume, 200, "volume tops out at 200%");

    s.step_rate(1);
    assert!((s.engine.speed() - 1.25).abs() < 0.01);
    s.set_rate(3.2);
    assert_eq!(s.rate(), 3.0, "speed snaps to the nearest step");
    s.set_rate(1.0);

    s.add_bookmark();
    let source = s.source().unwrap();
    assert_eq!(s.store.file_state(&source).bookmarks.len(), 1);
    assert_eq!(s.store.settings.recent[0], source);

    s.toggle_mute();
    assert!(s.engine.muted());
}

#[test]
fn transport_pause_stop_and_replay() {
    let Some(fx) = fixture() else { return };
    let mut s = session();
    s.toggle(); // nothing queued: no effect
    assert_eq!(s.state(), State::Idle);

    play(&mut s, &fx.path("single/film.mp4"));
    s.toggle();
    assert_eq!(s.state(), State::Paused);
    s.toggle();
    assert!(wait(&mut s, 3, |s| s.state() == State::Playing));

    s.skip(8_000);
    assert!(wait(&mut s, 3, |s| s.position_ms() >= 8_000));
    s.skip(-60_000);
    assert!(
        wait(&mut s, 3, |s| s.position_ms() < 3_000),
        "seeking before the start clamps to 0"
    );

    s.stop();
    assert!(wait(&mut s, 3, |s| s.state() == State::Idle));
    s.toggle();
    assert!(
        wait(&mut s, 8, |s| s.state() == State::Playing),
        "toggle replays the stopped file"
    );
}

#[test]
fn ab_loop_keeps_playback_inside_the_loop() {
    let Some(fx) = fixture() else { return };
    let mut s = session();
    play(&mut s, &fx.path("show/ep1.mp4"));
    s.seek_ms(2_000);
    assert!(wait(&mut s, 5, |s| (2_000..3_000).contains(&s.position_ms())));
    s.set_loop(Some(2_000), Some(4_000));
    let end = Instant::now() + Duration::from_secs(5);
    while Instant::now() < end {
        s.tick();
        assert!(
            s.position_ms() < 4_500,
            "left the loop at {} ms",
            s.position_ms()
        );
        sleep(Duration::from_millis(50));
    }
    s.ab_loop();
    assert_eq!(
        s.loop_points(),
        (None, None),
        "a full loop is cleared by the next press"
    );
    assert!(
        wait(&mut s, 6, |s| s.position_ms() > 5_000),
        "playback continues after clearing"
    );
}

#[test]
fn ab_loop_key_cycles_start_end_clear() {
    let Some(fx) = fixture() else { return };
    let mut s = session();
    play(&mut s, &fx.path("show/ep1.mp4"));
    s.ab_loop();
    let (a, b) = s.loop_points();
    assert!(a.is_some() && b.is_none(), "first press sets the start");
    assert!(wait(&mut s, 5, |s| s.position_ms() > a.unwrap() + 500));
    s.ab_loop();
    assert!(s.loop_points().1.is_some(), "second press sets the end");
    s.ab_loop();
    assert_eq!(s.loop_points(), (None, None), "third press clears");
}

#[test]
fn ab_loop_end_must_come_after_the_start() {
    let Some(fx) = fixture() else { return };
    let mut s = session();
    play(&mut s, &fx.path("show/ep1.mp4"));
    s.engine.set_paused(true);
    assert!(wait(&mut s, 3, |s| s.state() == State::Paused));
    s.ab_loop();
    s.ab_loop(); // time has not moved on, so this cannot be an end point
    assert_eq!(s.loop_points(), (None, None));
}

#[test]
fn continues_with_the_next_file_in_the_folder() {
    let Some(fx) = fixture() else { return };
    let mut s = session();
    play(&mut s, &fx.path("show/ep2.mp4"));
    s.seek_ms(28_500);
    assert!(wait(&mut s, 12, |s| s.queue.items.len() == 2
        && s.queue.current == Some(1)));
    assert!(
        s.source().unwrap().ends_with("ep10.mp4"),
        "natural order: ep2 is followed by ep10"
    );
}

#[test]
fn finishing_the_last_file_resets_its_resume_point() {
    let Some(fx) = fixture() else { return };
    let mut s = session();
    play(&mut s, &fx.path("single/film.mp4"));
    s.seek_ms(29_000);
    assert!(wait(&mut s, 10, |s| s.state() == State::Ended));
    let source = s.source().unwrap();
    assert_eq!(s.store.file_state(&source).position, 0);
    assert_eq!(s.queue.items.len(), 1, "nothing follows in this folder");
    s.toggle();
    assert!(
        wait(&mut s, 8, |s| s.state() == State::Playing
            && s.position_ms() < 5_000),
        "toggle replays a finished file"
    );
}

#[test]
fn chapters_and_frame_stepping() {
    let Some(fx) = fixture() else { return };
    let mut s = session();
    s.chapter(1);
    assert!(s.status().contains("NO CHAPTERS"));

    play(&mut s, &fx.path("chapters.mkv"));
    assert!(wait(&mut s, 3, |s| s.engine.chapter_count() == 2));
    s.chapter(1);
    assert!(
        wait(&mut s, 4, |s| s.position_ms() >= 9_500),
        "did not jump to the second chapter"
    );

    s.frame_forward();
    assert!(
        wait(&mut s, 3, |s| s.state() == State::Paused),
        "frame stepping pauses"
    );
    let here = settled_position(&mut s);
    s.frame_back();
    assert!(
        wait(&mut s, 3, |s| s.position_ms() < here),
        "stepping back moves to an earlier frame"
    );
    assert!(
        here - settled_position(&mut s) < 100,
        "back-step moves by one frame, not a jump"
    );
}

#[test]
fn track_cycling_and_per_file_track_memory() {
    let Some(fx) = fixture() else { return };
    let mut s = session();
    play(&mut s, &fx.path("tracks.mkv"));
    let audio = s.engine.tracks(TrackKind::Audio);
    assert_eq!(audio.len(), 2);
    assert_eq!(audio[0].label, "eng");
    let first = s.engine.selected_track(TrackKind::Audio);

    s.cycle_track(TrackKind::Audio);
    let second = s.engine.selected_track(TrackKind::Audio);
    assert_ne!(first, second);
    s.cycle_track(TrackKind::Audio);
    assert_eq!(
        s.engine.selected_track(TrackKind::Audio),
        first,
        "audio wraps around"
    );

    // Subtitles cycle through every track and then "off".
    let start = s.engine.selected_track(TrackKind::Subtitle);
    s.cycle_track(TrackKind::Subtitle);
    s.cycle_track(TrackKind::Subtitle);
    assert_eq!(
        s.engine.selected_track(TrackKind::Subtitle),
        start,
        "one subtitle track plus off is a cycle of two"
    );

    // Choose the second audio track and no subtitles, leave, and come back.
    s.cycle_track(TrackKind::Audio);
    s.engine.select_track(TrackKind::Subtitle, None);
    let chosen = s.engine.selected_track(TrackKind::Audio);
    s.add(&[fx.path("single/film.mp4")], true);
    assert!(wait(&mut s, 8, |s| s.state() == State::Playing
        && s.source().is_some_and(|p| p.ends_with("film.mp4"))));
    s.play_index(0, Some(0), false);
    assert!(wait(&mut s, 8, |s| s.engine.tracks(TrackKind::Audio).len() == 2));
    assert!(
        wait(&mut s, 3, |s| s.engine.selected_track(TrackKind::Audio)
            == chosen),
        "audio track not restored"
    );
    assert_eq!(
        s.engine.selected_track(TrackKind::Subtitle),
        None,
        "subtitles stay off"
    );
}

#[test]
fn cycling_without_tracks_says_so() {
    let Some(_fx) = fixture() else { return };
    let mut s = session();
    s.cycle_track(TrackKind::Subtitle);
    assert!(s.status().contains("NO TRACKS"));
}

#[test]
fn unreadable_media_reports_an_error_and_does_not_advance() {
    let Some(fx) = fixture() else { return };
    let mut s = session();
    s.add(&[fx.path("missing.mkv")], true);
    assert!(wait(&mut s, 5, |s| s.state() == State::Idle
        || s.state() == State::Ended));
    assert_eq!(s.queue.current, Some(0));
}
